// Step 1 of 3: deterministic scoring. Free, instant, and it never changes its mind.
// Code instead of a native IF-chain: the keyword and source weight maps live in
// 'Configure context', and native nodes cannot iterate a configurable map.
const config = $('Configure context').first().json;
const keywordWeights = config.rulesKeywords;
const sourceWeights = config.sourceWeights;

const scoredItems = [];
for (const item of $input.all()) {
  const article = item.json;
  const titleText = String(article.title || '').toLowerCase();
  const bodyText = (String(article.summary || '') + ' ' + String(article.content_excerpt || '')).toLowerCase();

  // A keyword in the headline is worth double a keyword buried in the body.
  // Word-boundary matching: 'ai' must not match inside 'bargain'.
  let keywordScore = 0;
  for (const [term, weight] of Object.entries(keywordWeights)) {
    const escapedTerm = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const termPattern = new RegExp(`\\b${escapedTerm}\\b`, 'i');
    if (termPattern.test(titleText)) keywordScore += weight * 2;
    else if (termPattern.test(bodyText)) keywordScore += weight;
  }
  const sourceScore = sourceWeights[article.source] || 0;
  const rulesScore = keywordScore + sourceScore;

  let rulesBand = 'pass';
  if (rulesScore < config.rulesRejectThreshold) rulesBand = 'reject';
  else if (rulesScore >= config.rulesHardWinThreshold) rulesBand = 'hardWin';

  scoredItems.push({ json: { ...article, rulesScore, rulesBand, embedText: `${article.title}. ${article.summary}` } });
}
return scoredItems;

// Step 2 of 3: group near-duplicate coverage of the same story.
// Code because similarity clustering needs a pairwise cosine matrix,
// which no native node expresses. Greedy single-link over 50 articles is instant.
// One item per STORY leaves this node, so the canvas count itself shows the dedup.
const config = $('Configure context').first().json;
const threshold = Number(config.clusterSimilarityThreshold);
const articles = $('Drop rejected noise').all().map(item => item.json);
const vectors = $input.first().json.vectors;
if (!Array.isArray(vectors) || vectors.length !== articles.length) {
  throw new Error(`Vector count (${vectors && vectors.length}) does not match article count (${articles.length})`);
}

function cosineSimilarity(vectorA, vectorB) {
  let dotProduct = 0;
  let magnitudeA = 0;
  let magnitudeB = 0;
  for (let dim = 0; dim < vectorA.length; dim++) {
    dotProduct += vectorA[dim] * vectorB[dim];
    magnitudeA += vectorA[dim] * vectorA[dim];
    magnitudeB += vectorB[dim] * vectorB[dim];
  }
  return dotProduct / (Math.sqrt(magnitudeA) * Math.sqrt(magnitudeB));
}

const clusters = [];
for (let articleIndex = 0; articleIndex < articles.length; articleIndex++) {
  let joinedExisting = false;
  for (const cluster of clusters) {
    if (cluster.some(memberIndex => cosineSimilarity(vectors[articleIndex], vectors[memberIndex]) >= threshold)) {
      cluster.push(articleIndex);
      joinedExisting = true;
      break;
    }
  }
  if (!joinedExisting) clusters.push([articleIndex]);
}

// The primary is picked deterministically: highest rules score, longer excerpt on ties.
// Every other member rides along on the primary as corroborating coverage.
const storyItems = [];
clusters.forEach((memberIndexes, clusterNumber) => {
  const primaryIndex = memberIndexes.reduce((bestIndex, candidateIndex) => {
    const bestArticle = articles[bestIndex];
    const candidateArticle = articles[candidateIndex];
    if (candidateArticle.rulesScore !== bestArticle.rulesScore) {
      return candidateArticle.rulesScore > bestArticle.rulesScore ? candidateIndex : bestIndex;
    }
    return String(candidateArticle.content_excerpt || '').length > String(bestArticle.content_excerpt || '').length
      ? candidateIndex : bestIndex;
  });
  const corroborating = memberIndexes
    .filter(memberIndex => memberIndex !== primaryIndex)
    .map(memberIndex => ({
      title: articles[memberIndex].title,
      source: articles[memberIndex].source,
      url: articles[memberIndex].url,
    }));
  storyItems.push({ json: {
    ...articles[primaryIndex],
    clusterId: clusterNumber + 1,
    clusterSize: memberIndexes.length,
    isPrimary: true,
    corroborating,
  }});
});
return storyItems;

// Writes every article's fate back to the seen ledger, matched by URL.
//
// Uses the outputs from the new weighted JEV scoring node rather than
// reconstructing the old GPT judge verdict.
//
// Statuses:
//   rejected_rules  - rejected before semantic/JEV processing
//   approved_rules  - rules hard-win, skipped JEV
//   approved_jev    - passed weighted JEV relevance scoring
//   rejected_jev    - failed weighted JEV relevance scoring
//   corroborating   - duplicate coverage of a primary story
//
// fetch_failed / fetch_abandoned rows are written by "Record fetch failure"
// and are skipped here so this node does not overwrite them.

const scoredArticles = $('Score with rules (Step 1)')
  .all()
  .map(item => item.json);

const storyPrimaries = $('Cluster stories (Step 2)')
  .all()
  .map(item => item.json);

// This is the node that now calculates the weighted JEV relevance score
// and outputs suggested_verdict, verdict_reason, judge_type, etc.
const scoredStories = $('Score and assemble ALL stories')
  .all()
  .map(item => item.json);

const fetchFailures = $('Merge')
  .all()
  .map(item => item.json)
  .filter(result => result.result_type === 'fetch_failure');

const fetchFailedUrls = new Set(
  fetchFailures.map(failure => failure.url)
);

const config = $('Configure context').first().json;
const runId = String($execution.id || 'manual');


// ---------------------------------------------------------
// Build scored-story lookup by cluster
// ---------------------------------------------------------

const scoredByCluster = {};

for (const scored of scoredStories) {
  scoredByCluster[scored.cluster_id] = scored;
}


// ---------------------------------------------------------
// Build outcome lookup by URL
// ---------------------------------------------------------

const outcomeByUrl = {};


// ---------------------------------------------------------
// Rules rejects
// ---------------------------------------------------------

for (const article of scoredArticles) {
  if (article.rulesBand === 'reject') {
    outcomeByUrl[article.url] = {
      status: 'rejected_rules',
      rules_score: article.rulesScore,
      reason:
        `Rules score ${article.rulesScore} below reject threshold ` +
        `${config.rulesRejectThreshold}`,
      cluster_id: '',
    };
  }
}


// ---------------------------------------------------------
// Cluster primaries + corroborating articles
// ---------------------------------------------------------

for (const story of storyPrimaries) {
  const scored = scoredByCluster[story.clusterId];

  let status;
  let reason;

  if (!scored) {
    status = 'rejected_jev';
    reason = 'Missing scoring result';
  } else if (scored.judge_type === 'rules') {
    status = 'approved_rules';
    reason = scored.verdict_reason;
  } else if (
    scored.judge_type === 'jev' &&
    scored.suggested_verdict === 'approved'
  ) {
    status = 'approved_jev';
    reason = scored.verdict_reason;
  } else {
    status = 'rejected_jev';
    reason = scored.verdict_reason || 'JEV relevance threshold not met';
  }

  outcomeByUrl[story.url] = {
    status,
    rules_score: story.rulesScore,
    reason,
    cluster_id: story.clusterId,
  };


  // -------------------------------------------------------
  // Corroborating / duplicate coverage
  // -------------------------------------------------------

  for (const member of story.corroborating || []) {
    const memberScored = scoredArticles.find(
      candidate => candidate.url === member.url
    );

    outcomeByUrl[member.url] = {
      status: 'corroborating',
      rules_score: memberScored ? memberScored.rulesScore : '',
      reason: `Duplicate coverage of: ${story.title}`,
      cluster_id: story.clusterId,
    };
  }
}


// Fetch failures already carry their own ledger status
for (const url of fetchFailedUrls) {
  delete outcomeByUrl[url];
}


// ---------------------------------------------------------
// Output
// ---------------------------------------------------------

return Object.entries(outcomeByUrl).map(([url, outcome]) => ({
  json: {
    url,
    ...outcome,
    run_id: runId,
  },
}));

// Score and assemble ALL stories.
//
// Rules hard-wins bypass JEV.
// All other stories are scored using JEV outputs.
//
// This node DOES NOT filter stories.
// Use an IF node afterwards to decide what continues.
//
// Weighted relevance model:
//   Regulatory relevance            30%
//   UK applicability                20%
//   Fintech/payments applicability  15%
//   Regulatory significance         15%
//   Firm actionability              10%
//   Client content value            10%
//
// Substantive depth is diagnostic only.
// Content quality is classification only.

const APPROVAL_THRESHOLD = 60;

const WEIGHTS = {
  regulatory_relevance: 30,
  uk_applicability: 20,
  fintech_payments_applicability: 15,
  regulatory_significance: 15,
  firm_actionability: 10,
  client_content_value: 10,
};

const REJECT_CATEGORIES = new Set([
  'consumer_finance',
  'product_marketing',
  'appointment_people_news',
  'evergreen_background',
  'thin_content',
  'other_off_niche',
]);

const CATEGORY_REJECT_CONFIDENCE = 0.75;


// ---------------------------------------------------------
// Input stories
// ---------------------------------------------------------

const storyPrimaries = $('Cluster stories (Step 2)')
  .all()
  .map(item => item.json);

const judgedPrimaries = storyPrimaries.filter(
  story => story.rulesBand !== 'hardWin'
);


// ---------------------------------------------------------
// Fetch failures
// ---------------------------------------------------------
// The fetch-and-judge loop tags every result with its story URL, so JEV
// outputs and fetch failures are matched to stories by URL, never by position.

const loopResults = $input
  .all()
  .map(item => item.json)
  .filter(result => result.result_type);

const fetchFailureByUrl = Object.fromEntries(
  loopResults
    .filter(result => result.result_type === 'fetch_failure')
    .map(failure => [failure.url, failure])
);

const jevResultByUrl = Object.fromEntries(
  loopResults
    .filter(result => result.result_type === 'jev')
    .map(result => [result.story_url, result])
);

const fetchedPrimaries = judgedPrimaries.filter(
  story => !fetchFailureByUrl[story.url]
);


// ---------------------------------------------------------
// Normalise JEV response
// ---------------------------------------------------------

function getJevResult(raw) {
  if (!raw) return null;

  let result = raw.output ?? raw;

  if (typeof result === 'string') {
    try {
      result = JSON.parse(result);
    } catch {
      return null;
    }
  }

  if (!result || typeof result !== 'object') {
    return null;
  }

  return result.answers ?? result;
}


// ---------------------------------------------------------
// JEV helpers
// ---------------------------------------------------------

function getScore(answers, key) {
  const answer = answers?.[key];

  if (answer == null) return null;

  if (typeof answer.score === 'number') {
    return answer.score;
  }

  if (typeof answer === 'number') {
    return answer;
  }

  return null;
}


function getConfidence(answers, key) {
  const confidence = answers?.[key]?.confidence;

  return typeof confidence === 'number'
    ? confidence
    : null;
}


function getChoice(answers, key) {
  const answer = answers?.[key];

  if (answer == null) return null;

  if (typeof answer.choice === 'string') {
    return answer.choice;
  }

  if (typeof answer === 'string') {
    return answer;
  }

  return null;
}


// ---------------------------------------------------------
// Weighted relevance calculation
// ---------------------------------------------------------

function calculateRelevance(answers) {
  const scores = {
    regulatory_relevance:
      getScore(answers, 'regulatory_relevance'),

    uk_applicability:
      getScore(answers, 'uk_applicability'),

    fintech_payments_applicability:
      getScore(answers, 'fintech_payments_applicability'),

    regulatory_significance:
      getScore(answers, 'regulatory_significance'),

    firm_actionability:
      getScore(answers, 'firm_actionability'),

    client_content_value:
      getScore(answers, 'client_content_value'),
  };

  const missingScores = Object.entries(scores)
    .filter(([, value]) => typeof value !== 'number')
    .map(([key]) => key);

  if (missingScores.length > 0) {
    return {
      valid: false,
      score: null,
      scores,
      missingScores,
    };
  }

  let total = 0;

  for (const [key, weight] of Object.entries(WEIGHTS)) {
    total += (scores[key] / 4) * weight;
  }

  return {
    valid: true,
    score: Math.round(total * 100) / 100,
    scores,
    missingScores: [],
  };
}


// ---------------------------------------------------------
// Score band
// ---------------------------------------------------------

function getScoreBand(score) {
  if (score === null) return 'invalid';
  if (score < 40) return 'reject';
  if (score < 60) return 'weak';
  if (score < 75) return 'candidate';
  return 'strong';
}


// ---------------------------------------------------------
// Build result lookup
// ---------------------------------------------------------

const verdictByCluster = {};


// ---------------------------------------------------------
// Rules hard wins
// ---------------------------------------------------------

for (const story of storyPrimaries) {
  if (story.rulesBand === 'hardWin') {
    verdictByCluster[story.clusterId] = {
      suggestedVerdict: 'approved',
      reason: 'Rules hard win - skipped JEV',
      judgeType: 'rules',

      relevanceScore: null,
      scoreBand: 'rules_hard_win',

      categoryHardReject: false,

      jev: null,
    };
  }
}


// ---------------------------------------------------------
// Fetch failures - rejected this run, retried on the next
// ---------------------------------------------------------

for (const story of judgedPrimaries) {
  const failure = fetchFailureByUrl[story.url];

  if (failure) {
    verdictByCluster[story.clusterId] = {
      suggestedVerdict: 'rejected',
      reason: failure.reason,
      judgeType: failure.status,

      relevanceScore: null,
      scoreBand: 'invalid',

      categoryHardReject: false,

      jev: null,
    };
  }
}


// ---------------------------------------------------------
// Process JEV results
// ---------------------------------------------------------

fetchedPrimaries.forEach(story => {
  const rawJudgeOutput = jevResultByUrl[story.url];
  const answers = getJevResult(rawJudgeOutput);

  if (!answers) {
    verdictByCluster[story.clusterId] = {
      suggestedVerdict: 'rejected',
      reason: 'No valid JEV output received',
      judgeType: 'jev',

      relevanceScore: null,
      scoreBand: 'invalid',

      categoryHardReject: false,

      jev: null,
    };

    return;
  }


  // -------------------------------------------------------
  // Calculate weighted relevance
  // -------------------------------------------------------

  const relevance = calculateRelevance(answers);

  if (!relevance.valid) {
    verdictByCluster[story.clusterId] = {
      suggestedVerdict: 'rejected',

      reason:
        `Incomplete JEV output - missing scores: ` +
        relevance.missingScores.join(', '),

      judgeType: 'jev',

      relevanceScore: null,
      scoreBand: 'invalid',

      categoryHardReject: false,

      jev: answers,
    };

    return;
  }


  // -------------------------------------------------------
  // Content classification
  // -------------------------------------------------------

  const contentQuality =
    getChoice(answers, 'content_quality');

  const contentQualityConfidence =
    getConfidence(answers, 'content_quality');

  const categoryHardReject =
    REJECT_CATEGORIES.has(contentQuality) &&
    contentQualityConfidence !== null &&
    contentQualityConfidence >= CATEGORY_REJECT_CONFIDENCE;


  // -------------------------------------------------------
  // Suggested decision
  // -------------------------------------------------------

  const passesScore =
    relevance.score >= APPROVAL_THRESHOLD;

  const suggestedApproved =
    passesScore && !categoryHardReject;

  const scoreBand =
    getScoreBand(relevance.score);


  // -------------------------------------------------------
  // Human-readable diagnostic
  // -------------------------------------------------------

  let reason;

  if (categoryHardReject) {
    reason =
      `High-confidence rejection classification: ` +
      `${contentQuality} ` +
      `(${Math.round(contentQualityConfidence * 100)}% confidence). ` +
      `Weighted relevance score: ${relevance.score}/100`;
  } else if (!passesScore) {
    reason =
      `Weighted relevance score ${relevance.score}/100 ` +
      `is below threshold ${APPROVAL_THRESHOLD}/100. ` +
      `Content classification: ${contentQuality || 'unknown'}`;
  } else {
    reason =
      `Weighted relevance score ${relevance.score}/100 ` +
      `meets threshold ${APPROVAL_THRESHOLD}/100. ` +
      `Content classification: ${contentQuality || 'unknown'}`;
  }


  verdictByCluster[story.clusterId] = {
    suggestedVerdict:
      suggestedApproved ? 'approved' : 'rejected',

    reason,
    judgeType: 'jev',

    relevanceScore: relevance.score,
    scoreBand,

    categoryHardReject,

    jev: answers,
  };
});


// ---------------------------------------------------------
// Run-level metrics
// ---------------------------------------------------------

const articlesIn =
  $('Read source articles').all().length;

const survivedRules =
  $('Drop rejected noise').all().length;

const runId =
  $execution.id || 'manual';

const runAt =
  new Date().toISOString();

const runSignature =
  `${articlesIn}-${survivedRules}-${storyPrimaries.length}-${judgedPrimaries.length}`;

const rulesHardWins =
  storyPrimaries.filter(
    story => story.rulesBand === 'hardWin'
  ).length;


// ---------------------------------------------------------
// Assemble ALL stories
// ---------------------------------------------------------

const packageRows = [];

for (const story of storyPrimaries) {

  const clusterVerdict =
    verdictByCluster[story.clusterId] || {
      suggestedVerdict: 'rejected',
      reason: 'Missing scoring result',
      judgeType: 'unknown',

      relevanceScore: null,
      scoreBand: 'invalid',

      categoryHardReject: false,

      jev: null,
    };


  const corroborating =
    (story.corroborating || [])
      .map(member =>
        `${member.title} - ${member.source} (${member.url})`
      )
      .join(' | ');


  const jev = clusterVerdict.jev;


  // -------------------------------------------------------
  // JEV scores
  // -------------------------------------------------------

  const regulatoryRelevance =
    getScore(jev, 'regulatory_relevance');

  const ukApplicability =
    getScore(jev, 'uk_applicability');

  const fintechApplicability =
    getScore(jev, 'fintech_payments_applicability');

  const firmActionability =
    getScore(jev, 'firm_actionability');

  const regulatorySignificance =
    getScore(jev, 'regulatory_significance');

  const substantiveDepth =
    getScore(jev, 'substantive_depth');

  const clientContentValue =
    getScore(jev, 'client_content_value');

  const contentQuality =
    getChoice(jev, 'content_quality');

  const contentQualityConfidence =
    getConfidence(jev, 'content_quality');


  // -------------------------------------------------------
  // Weighted contributions
  // -------------------------------------------------------

  const regulatoryRelevancePoints =
    regulatoryRelevance !== null
      ? Math.round(
          ((regulatoryRelevance / 4) *
            WEIGHTS.regulatory_relevance) * 100
        ) / 100
      : null;

  const ukApplicabilityPoints =
    ukApplicability !== null
      ? Math.round(
          ((ukApplicability / 4) *
            WEIGHTS.uk_applicability) * 100
        ) / 100
      : null;

  const fintechApplicabilityPoints =
    fintechApplicability !== null
      ? Math.round(
          ((fintechApplicability / 4) *
            WEIGHTS.fintech_payments_applicability) * 100
        ) / 100
      : null;

  const regulatorySignificancePoints =
    regulatorySignificance !== null
      ? Math.round(
          ((regulatorySignificance / 4) *
            WEIGHTS.regulatory_significance) * 100
        ) / 100
      : null;

  const firmActionabilityPoints =
    firmActionability !== null
      ? Math.round(
          ((firmActionability / 4) *
            WEIGHTS.firm_actionability) * 100
        ) / 100
      : null;

  const clientContentValuePoints =
    clientContentValue !== null
      ? Math.round(
          ((clientContentValue / 4) *
            WEIGHTS.client_content_value) * 100
        ) / 100
      : null;


  // -------------------------------------------------------
  // Output ALL stories
  // -------------------------------------------------------

  packageRows.push({
    json: {

      run_id: runId,
      run_at: runAt,
      run_signature: runSignature,

      cluster_id: story.clusterId,

      best_title: story.title,
      best_source: story.source,
      best_url: story.url,


      // Rules stage
      rules_score: story.rulesScore,
      rules_band: story.rulesBand,


      // Suggested relevance decision
      judge_type: clusterVerdict.judgeType,

      relevance_score:
        clusterVerdict.relevanceScore,

      relevance_score_band:
        clusterVerdict.scoreBand,

      relevance_threshold:
        APPROVAL_THRESHOLD,

      suggested_verdict:
        clusterVerdict.suggestedVerdict,

      verdict_reason:
        clusterVerdict.reason,


      // JEV classification
      jev_content_quality:
        contentQuality,

      jev_content_quality_confidence:
        contentQualityConfidence,

      jev_category_hard_reject:
        clusterVerdict.categoryHardReject,


      // JEV raw component scores
      jev_regulatory_relevance:
        regulatoryRelevance,

      jev_uk_applicability:
        ukApplicability,

      jev_fintech_payments_applicability:
        fintechApplicability,

      jev_regulatory_significance:
        regulatorySignificance,

      jev_firm_actionability:
        firmActionability,

      jev_substantive_depth:
        substantiveDepth,

      jev_client_content_value:
        clientContentValue,


      // Weighted point contributions
      relevance_points_regulatory:
        regulatoryRelevancePoints,

      relevance_points_uk:
        ukApplicabilityPoints,

      relevance_points_fintech_payments:
        fintechApplicabilityPoints,

      relevance_points_regulatory_significance:
        regulatorySignificancePoints,

      relevance_points_firm_actionability:
        firmActionabilityPoints,

      relevance_points_client_content_value:
        clientContentValuePoints,


      // JEV confidence values
      jev_regulatory_relevance_confidence:
        getConfidence(jev, 'regulatory_relevance'),

      jev_uk_applicability_confidence:
        getConfidence(jev, 'uk_applicability'),

      jev_fintech_payments_applicability_confidence:
        getConfidence(
          jev,
          'fintech_payments_applicability'
        ),

      jev_regulatory_significance_confidence:
        getConfidence(jev, 'regulatory_significance'),

      jev_firm_actionability_confidence:
        getConfidence(jev, 'firm_actionability'),

      jev_substantive_depth_confidence:
        getConfidence(jev, 'substantive_depth'),

      jev_client_content_value_confidence:
        getConfidence(jev, 'client_content_value'),


      // Cluster information
      corroborating_sources:
        corroborating ||
        'none - single-source story',

      articles_in_cluster:
        story.clusterSize,


      // Run metrics
      run_articles_in:
        articlesIn,

      run_survived_rules:
        survivedRules,

      run_unique_stories:
        storyPrimaries.length,

      run_jev_calls:
        fetchedPrimaries.length,

      run_rules_hard_wins:
        rulesHardWins,
    },
  });
}


return packageRows;
